-- Canonical blank locale drafts and exact eligible reference closure for saved private preview.
CREATE FUNCTION gcms_m4.blank_content(k text,c jsonb,l text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$DECLARE out jsonb:=c;name text;s jsonb;sections jsonb:='[]';pair jsonb;pairs jsonb:='[]';side text;BEGIN
 FOREACH name IN ARRAY ARRAY['title','summary','quote','attribution','professionalTitle','inclusions','notes'] LOOP IF out ? name THEN out:=jsonb_set(out,ARRAY[name],'""');END IF;END LOOP;
 IF out ? 'body' THEN out:=jsonb_set(out,'{body}',gcms_s02.plain_document(''));END IF;IF out ? 'seo' THEN out:=jsonb_set(out,'{seo}','{"title":"","description":""}');END IF;IF out ? 'credentials' THEN out:=jsonb_set(out,'{credentials}','[]');END IF;
 FOREACH name IN ARRAY ARRAY['image','coverImage'] LOOP IF out ? name AND out->name<>'null'::jsonb THEN out:=jsonb_set(out,ARRAY[name,'alt'],'""');END IF;END LOOP;
 IF k='promotion' THEN out:=jsonb_set(out,'{conditions}','""');END IF;
 IF k='gallery' THEN FOR pair IN SELECT value FROM jsonb_array_elements(out->'pairs') LOOP FOREACH side IN ARRAY ARRAY['before','after'] LOOP pair:=jsonb_set(pair,ARRAY[side,'alt'],'""');pair:=jsonb_set(pair,ARRAY[side,'caption'],'""');END LOOP;pairs:=pairs||jsonb_build_array(pair);END LOOP;out:=jsonb_set(out,'{pairs}',pairs);END IF;
 IF k IN ('home','page','landing') THEN FOR s IN SELECT value FROM jsonb_array_elements(out->'sections') LOOP FOREACH name IN ARRAY ARRAY['title','text'] LOOP IF s ? name THEN s:=jsonb_set(s,ARRAY[name],'""');END IF;END LOOP;IF s ? 'body' THEN s:=jsonb_set(s,'{body}',gcms_s02.plain_document(''));END IF;IF s->>'type'='hero' THEN IF s->'image'<>'null'::jsonb THEN s:=jsonb_set(s,'{image,alt}','""');END IF;IF s->'action'<>'null'::jsonb THEN s:=jsonb_set(s,'{action,label}','""');s:=jsonb_set(s,'{action,target,locale}',to_jsonb(l));END IF;END IF;sections:=sections||jsonb_build_array(s);END LOOP;out:=jsonb_set(out,'{sections}',sections);END IF;RETURN out;
END $$;
CREATE OR REPLACE FUNCTION gcms_m4.variant_view(t text,k text,r text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d gcms_m4.variant%ROWTYPE;p gcms_m4.publication%ROWTYPE;legacy record;content jsonb;state jsonb;BEGIN
 PERFORM gcms_s05.authorize(t,true);state:=gcms_m4.legacy_state(t,k,r);SELECT * INTO d FROM gcms_m4.variant WHERE tenant_id=t AND kind=k AND resource_id=r AND locale=l;
 IF d.resource_id IS NOT NULL THEN SELECT * INTO p FROM gcms_m4.publication WHERE tenant_id=t AND id=d.active_publication_id;RETURN jsonb_build_object('id',r,'tenantId',t,'kind',k,'locale',l,'version',d.version,'publicationVersion',d.publication_version,'publicationRevision',d.publication_revision,'publishedVersion',p.draft_version,'activePublication',d.active_publication_id IS NOT NULL,'publicationId',d.active_publication_id,'slugLocked',true,'updatedAt',d.updated_at,'content',d.content,'legacy',false,'virtual',false,'legacySource',CASE WHEN state IS NULL THEN NULL ELSE jsonb_build_object('captured',d.legacy_guard,'current',state) END);END IF;
 IF k='config' THEN SELECT * INTO legacy FROM gcms_s02.site_draft WHERE tenant_id=t;IF legacy.tenant_id IS NULL THEN RETURN NULL;END IF;
 content:=jsonb_build_object('name',legacy.name,'logo',NULL,'theme','clarity','themeVersion',1,'palette','teal','font','system','layout','comfortable','footer',jsonb_build_object('intro',CASE WHEN l='vi' THEN legacy.footer_intro ELSE '' END,'body',CASE WHEN l='vi' THEN legacy.footer_body ELSE gcms_s02.plain_document('') END),'menu','[]'::jsonb);
 ELSIF k='service' THEN SELECT * INTO legacy FROM gcms_s02.service_draft WHERE tenant_id=t AND id=r;IF legacy.id IS NULL THEN RETURN NULL;END IF;content:=(SELECT gcms_s08.service_content(sd) FROM gcms_s02.service_draft sd WHERE sd.tenant_id=t AND sd.id=r)||jsonb_build_object('contentLinks',jsonb_build_object('references',coalesce((SELECT refs FROM gcms_m3.service_links_draft WHERE tenant_id=t AND service_id=r),'[]')));
 ELSIF gcms_m3.kind(k) THEN SELECT * INTO legacy FROM gcms_m3.resource WHERE tenant_id=t AND id=r AND kind=k;IF legacy.id IS NULL THEN RETURN NULL;END IF;content:=legacy.content;
 ELSIF k IN ('home','page','landing','promotion') THEN IF NOT EXISTS(SELECT 1 FROM gcms_m4.identity WHERE tenant_id=t AND kind=k AND id=r) THEN RETURN NULL;END IF;SELECT source.content INTO content FROM gcms_m4.variant source WHERE source.tenant_id=t AND source.kind=k AND source.resource_id=r ORDER BY (source.locale='vi') DESC LIMIT 1;IF content IS NULL THEN RETURN NULL;END IF;content:=gcms_m4.blank_content(k,content,l);
 ELSE RETURN NULL;END IF;
 IF l='en' AND k<>'config' AND (k='service' OR gcms_m3.kind(k)) THEN content:=gcms_m4.blank_content(k,content,l);END IF;
 RETURN jsonb_build_object('id',r,'tenantId',t,'kind',k,'locale',l,'version',CASE WHEN k IN ('config','home','page','landing','promotion') THEN 0 ELSE legacy.version END,'publicationVersion',CASE WHEN l='vi' THEN coalesce((state->>'publicationVersion')::integer,0) ELSE 0 END,'publicationRevision',CASE WHEN l='vi' THEN coalesce((state->>'publicationRevision')::integer,0) ELSE 0 END,'publishedVersion',NULL,'activePublication',l='vi' AND state->>'pointer' IS NOT NULL,'publicationId',CASE WHEN l='vi' THEN state->'pointer' ELSE 'null'::jsonb END,'slugLocked',true,'updatedAt',clock_timestamp(),'content',content,'legacy',k='service' OR gcms_m3.kind(k),'virtual',true,'legacySource',CASE WHEN state IS NULL THEN NULL ELSE jsonb_build_object('captured',NULL,'current',state) END);
END $$;



CREATE FUNCTION gcms_m4.preview_refs(t text,k text,r text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE draft jsonb;raw jsonb;pin jsonb;child jsonb;out jsonb:='[]';seen text[]:='{}';key text;site_slug text;BEGIN
 PERFORM gcms_s05.authorize(t,true);draft:=gcms_m4.variant_view(t,k,r,l);IF draft IS NULL THEN RETURN NULL;END IF;SELECT slug INTO site_slug FROM gcms_s02.site_draft WHERE tenant_id=t;
 BEGIN PERFORM gcms_m4.admit_refs(t,k,l,draft->'content',gcms_m4.pin_refs(t,k,r,l,draft->'content'));EXCEPTION WHEN check_violation THEN RETURN '[]';END;
 FOR raw IN SELECT * FROM gcms_m4.refs(k,draft->'content') LOOP key:=(raw->>'kind')||':'||(raw->>'id')||':'||(raw->>'publicationId');IF key=ANY(seen) THEN CONTINUE;END IF;seen:=array_append(seen,key);child:=NULL;
  BEGIN pin:=gcms_m4.pin_refs(t,'promotion',r,l,jsonb_build_object('references',jsonb_build_array(raw)))->0;EXCEPTION WHEN check_violation THEN CONTINUE;END;
  IF pin->'legacy'='true'::jsonb THEN
   IF pin->>'kind'='service' THEN SELECT jsonb_build_object('id',p.service_id,'kind','service','legacy',true,'locale','vi','publicationId',p.id,'publicationVersion',p.publication_version,'title',p.closure->'service'->'title','slug',p.closure->'service'->'slug','path',gcms_m4.path(site_slug,'vi','service',p.closure->'service'->>'slug'),'content',(gcms_s08.eligible_closure(t,p.closure)->'service')-ARRAY['coverImage','contentLinks'],'references','[]'::jsonb,'media','[]'::jsonb) INTO child FROM gcms_s02.publication_snapshot p WHERE p.tenant_id=t AND p.service_id=pin->>'id' AND p.id=pin->>'publicationId';
   ELSE child:=gcms_m3.public_projection(t,pin->>'id',pin->>'publicationId');IF child IS NOT NULL THEN child:=jsonb_build_object('id',child->'id','kind',child->'kind','legacy',true,'locale','vi','publicationId',child->'publicationId','publicationVersion',child->'publicationVersion','title',child->'content'->'title','slug',child->'content'->'slug','path',gcms_m4.path(site_slug,'vi',child->>'kind',child->'content'->>'slug'),'content',child->'content','references',gcms_m4.legacy_refs(t,child->'references'),'media',child->'media');END IF;END IF;
  ELSE child:=gcms_m4.project(t,pin->>'kind',pin->>'id',l,pin->>'publicationId');IF child IS NOT NULL THEN child:=jsonb_build_object('id',child->'id','kind',child->'kind','legacy',false,'locale',l,'publicationId',child->'publicationId','publicationVersion',child->'publicationVersion','title',child->'content'->'title','slug',child->'content'->'slug','path',gcms_m4.path(site_slug,l,child->>'kind',child->'content'->>'slug'),'content',child->'content','references',child->'references','media',child->'media');END IF;END IF;
  IF child IS NOT NULL THEN out:=out||jsonb_build_array(child);END IF;
 END LOOP;RETURN out;
END $$;
CREATE OR REPLACE FUNCTION gcms_m4.preview_issues(t text,k text,r text,l text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE d jsonb;a jsonb;pins jsonb;issues jsonb:='[]';BEGIN
 PERFORM gcms_s05.authorize(t,true);d:=gcms_m4.variant_view(t,k,r,l);IF d IS NULL THEN RETURN '["RESOURCE_UNAVAILABLE"]';END IF;IF d->'virtual'='true'::jsonb THEN issues:=issues||'"SAVE_DRAFT_FIRST"'::jsonb;END IF;
 BEGIN pins:=gcms_m4.pin_refs(t,k,r,l,d->'content');BEGIN PERFORM gcms_m4.admit_refs(t,k,l,d->'content',pins);EXCEPTION WHEN check_violation THEN issues:=issues||'"PUBLIC_GRAPH_LIMIT"'::jsonb;END;EXCEPTION WHEN check_violation THEN issues:=issues||'"REFERENCE_UNAVAILABLE"'::jsonb;END;
 IF k IN ('case','gallery','testimonial') AND NOT gcms_m4.text_allowed(t,k,r,l,(d->>'version')::integer) THEN issues:=issues||'"TEXT_PERMISSION_REQUIRED"'::jsonb;END IF;
 FOR a IN SELECT * FROM gcms_m4.assets(k,d->'content') LOOP IF NOT gcms_m4.asset_allowed(t,k,r,l,(d->>'version')::integer,a) THEN issues:=issues||'"MEDIA_PERMISSION_OR_READINESS"'::jsonb;END IF;END LOOP;RETURN issues;
END $$;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA gcms_m4 FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gcms_m4.preview_refs(text,text,text,text) TO gcms_s02_tenant;
CREATE FUNCTION gcms_m4.private_target_path(t text,target jsonb,allow_fallback boolean) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN PERFORM gcms_s05.authorize(t,true);RETURN gcms_m4.target_path(t,target,allow_fallback);END $$;
REVOKE ALL ON FUNCTION gcms_m4.private_target_path(text,jsonb,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gcms_m4.private_target_path(text,jsonb,boolean) TO gcms_s02_tenant;
